import { esc } from '../lib/content.js';

// All four answers were generated by an AI model. B and C were prompted to imitate
// a hurried student and a non-native English writer. The reveal says so.
const QUESTION = 'Seminar task (max 150 words): What does resilience mean in a social-ecological system, and why does it matter for managing a fishery?';
const ANSWERS = [
  {
    id: 'A',
    text: 'Resilience refers to the capacity of a social-ecological system to absorb disturbances, adapt to change and continue to function without shifting into a qualitatively different state. In fisheries, this means looking beyond maximum sustainable yield. A fish stock embedded in a degraded food web, or a fishing community dependent on a single species, may appear productive until a shock such as a heatwave or a market collapse pushes it past a threshold. Managing for resilience therefore involves maintaining diversity (of species, habitats and livelihoods), monitoring slow variables like nutrient loading or age structure, and building institutions that can learn and adjust. The collapse of Baltic cod illustrates how overfishing, eutrophication and climate change can interact to erode resilience long before the crisis becomes visible.',
    prompt: 'No style instructions. This is what a chatbot gives you by default.',
  },
  {
    id: 'B',
    text: 'So resilience is basically about whether a system can take a hit and bounce back, or adapt, without turning into something totally different (Holling 1973 was the first to really say this for ecology I think). For fisheries it matters because you can fish a stock "sustainably" on paper and still make the whole system more fragile. Like with Baltic cod, it wasnt just overfishing, it was also low oxygen and seals and warmer water all together, and the managment kept looking at one number. I think the main point is you have to manage the slow stuff (habitat, age of the fish, the fishers jobs) not just the catch quota. Otherwise you dont notice until its too late.',
    prompt: 'Asked to write like a tired second-year student: casual, a couple of typos, one "I think".',
  },
  {
    id: 'C',
    text: 'Resilience in social-ecological system is the ability to keep the main functions and identity when there is disturbance, for example a storm or a price change. It is not same as stability, because system can change and adapt and still be resilient. For fishery it is important because fish, fishers and rules are connected. If the managers only control the quota, they can miss other drivers, like eutrophication or climate. In my home region the fishers changed to other species when one stock declined, and this was a kind of adaptation. But if all species decline, there is no option left. So diversity of species and of income gives more resilience.',
    prompt: 'Asked to write as a student whose first language isn\'t English, with a personal example.',
  },
  {
    id: 'D',
    text: 'Holling (1973) distinguished resilience, the ability of a system to persist through change, from stability, its tendency to return to equilibrium. Social-ecological resilience extends this to coupled human and natural systems. For fisheries management the key implication is humility about prediction: thresholds are often only identified after they are crossed. Practical responses include precautionary harvest rules, protecting spawning habitat and older fish, and co-management arrangements that let local knowledge feed into decisions quickly.',
    prompt: 'Asked for a short, academic answer with one citation.',
  },
];

export default function spot(el, { store }) {
  let guesses = { ...(store.get().spot || {}) };
  let revealed = Object.keys(guesses).length === ANSWERS.length && store.get().spotRevealed;

  const draw = (focusSel) => {
    const allGuessed = ANSWERS.every((a) => guesses[a.id]);
    el.innerHTML = `<div class="card">
      <p class="q-label">${esc(QUESTION)}</p>
      <p class="hint">Read each answer and decide: written by a student, or by AI?</p>
      <div class="spot-list">${ANSWERS.map((a) => `
        <div class="spot-item">
          <p class="spot-label">Answer ${a.id}</p>
          <blockquote class="spot-text">${esc(a.text)}</blockquote>
          <div class="choice-row" role="group" aria-label="Answer ${a.id}: your guess">
            ${['Student', 'AI'].map((g) => `<button type="button" class="chip" data-a="${a.id}" data-g="${g}" aria-pressed="${guesses[a.id] === g}" ${revealed ? 'disabled' : ''}>${g}</button>`).join('')}
          </div>
          ${revealed ? `<p class="spot-reveal"><strong>AI.</strong> ${esc(a.prompt)}</p>` : ''}
        </div>`).join('')}
      </div>
      <div aria-live="polite">${revealed ? revealHtml() : `<p style="margin:0"><button type="button" class="btn" data-reveal ${allGuessed ? '' : 'disabled'}>${allGuessed ? 'Reveal' : `Guess all four to reveal (${Object.keys(guesses).length}/4)`}</button></p>`}</div>
    </div>`;
    el.querySelectorAll('[data-a]').forEach((b) => b.addEventListener('click', () => {
      guesses[b.dataset.a] = b.dataset.g;
      store.update((s) => { s.spot = { ...guesses }; });
      draw(`[data-a="${b.dataset.a}"][data-g="${b.dataset.g}"]`);
    }));
    el.querySelector('[data-reveal]')?.addEventListener('click', () => {
      revealed = true;
      store.update((s) => { s.spotRevealed = true; });
      draw('.spot-result');
    });
    el.querySelector('[data-again]')?.addEventListener('click', () => {
      guesses = {}; revealed = false;
      store.update((s) => { s.spot = {}; s.spotRevealed = false; });
      draw('[data-a]');
    });
    if (focusSel) el.querySelector(focusSel)?.focus();
  };

  const revealHtml = () => {
    const saidStudent = ANSWERS.filter((a) => guesses[a.id] === 'Student').length;
    return `<div class="result-note spot-result" tabindex="-1">
      <p><strong>All four were written by AI.</strong> ${saidStudent ? `You took ${saidStudent} for a student's work.` : 'You called them all. Most people don\'t.'} Two of them were asked to sound like a student, with typos, hedging and a personal example. It took one sentence of instructions each.</p>
      <p>What this shows: typos, an awkward phrase, a personal anecdote or a correct citation are not evidence either way. Nor is polish. A student who writes well isn't suspect, and a student who writes badly isn't cleared.</p>
      <p>Four answers is a small test, and a rigged one. But it matches larger studies: when researchers slipped AI-written answers into real university exams, markers missed nearly all of them (Scarfe et al. 2024, on the <a href="#/p/sources">sources page</a>).</p>
      <p style="margin:0"><button type="button" class="btn small secondary" data-again>Try again</button></p></div>`;
  };
  draw();
}
